import org.junit.Test;
import org.junit.Assert;
import static org.mockito.Mockito.*;

import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import ch.jalu.configme.configurationdata.PropertyListBuilder;

import java.util.List;
import java.util.Map;

public class PropertyListBuilderTest {

    @Test
    public void addNullPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        try {
            propertyListBuilder.add(null);
            Assert.fail("Expected ConfigMeException was not thrown");
        } catch (ConfigMeException ex) {
            Assert.assertTrue(true); // Expected exception caught
        }
    }

    @Test
    public void addNotNullPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property mockProperty = mock(Property.class);

        try {
            propertyListBuilder.add(mockProperty);
            Assert.assertTrue(true); // No exception thrown
        } catch (ConfigMeException ex) {
            Assert.fail("Unexpected ConfigMeException was thrown");
        }
    }

    @Test
    public void createEmptyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        List<Property<?>> propertyList = propertyListBuilder.create();

        Assert.assertTrue(propertyList.isEmpty());
    }

    @Test
    public void createNotEmptyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property mockProperty = mock(Property.class);
        propertyListBuilder.add(mockProperty);

        List<Property<?>> propertyList = propertyListBuilder.create();

        Assert.assertFalse(propertyList.isEmpty());
    }

    @Test
    public void getRootEntriesEmptyMapTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        Map<String, Object> map = propertyListBuilder.getRootEntries();

        Assert.assertTrue(map.isEmpty());
    }

    @Test
    public void getRootEntriesNotEmptyMapTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<String> mockProperty = mock(Property.class);
        when(mockProperty.getPath()).thenReturn("key");
        when(mockProperty.getValue()).thenReturn("value");
        propertyListBuilder.add(mockProperty);

        Map<String, Object> map = propertyListBuilder.getRootEntries();

        Assert.assertFalse(map.isEmpty());
        Assert.assertEquals("value", map.get("key"));
    }
}
